const EXPECTED_ORIGIN = 'https://pebble-public-messages.niko370669.chatgpt.site';
const SECURITY = {
  'Cache-Control': 'no-store',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'same-origin',
  'Content-Security-Policy': "default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'self' https://chatgpt.com https://*.chatgpt.com",
};
const json = (body, status = 200, extra = {}) => new Response(JSON.stringify(body), {
  status, headers: { ...SECURITY, 'Content-Type': 'application/json; charset=utf-8', ...extra },
});
const text = (body, type) => new Response(body, { headers: { ...SECURITY, 'Content-Type': type } });

async function boundedJson(stream, limit) {
  if (!stream) throw new Error('empty');
  const reader = stream.getReader();
  const chunks = []; let size = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.length;
      if (size > limit) { await reader.cancel(); throw new Error('too_large'); }
      chunks.push(value);
    }
  } finally { reader.releaseLock(); }
  const bytes = new Uint8Array(size); let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
  return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
}

// Passive, coarse diagnostics only: no cookies, canvas fingerprinting, or raw IP storage.
export async function senderMetadata(request, env, now = new Date()) {
  const ua = (request.headers.get('User-Agent') || '').slice(0, 512);
  const ip = request.headers.get('CF-Connecting-IP');
  const country = request.cf?.country;
  const asn = request.cf?.asn;
  const sender = {
    source: 'pebble-inbox', fingerprint: null, fingerprintDay: null,
    country: typeof country === 'string' && /^[A-Z]{2}$/.test(country) ? country : null,
    asn: Number.isSafeInteger(asn) && asn > 0 && asn <= 4294967295 ? asn : null,
    browser: /Edg(?:e|A|iOS)?\//.test(ua) ? 'Edge' : /(?:Firefox|FxiOS)\//.test(ua) ? 'Firefox' : /(?:Chrome|CriOS)\//.test(ua) ? 'Chrome' : /Safari\//.test(ua) ? 'Safari' : 'Other',
    device: /iPad|Tablet|Android(?!.*Mobile)/i.test(ua) ? 'tablet' : /Mobile|iPhone/i.test(ua) ? 'mobile' : /Windows|Macintosh|X11|Linux/i.test(ua) ? 'desktop' : 'unknown',
  };
  // Missing/short keys disable the identifier, never fall back to an unkeyed IP hash.
  // GPC opts out of grouping. CF-Connecting-IP must come from the deployed edge.
  if (typeof env.PEBBLE_SENDER_HASH_KEY === 'string' && env.PEBBLE_SENDER_HASH_KEY.length >= 32 &&
      ip && ip.length <= 64 && request.headers.get('Sec-GPC') !== '1') {
    const day = now.toISOString().slice(0, 10);
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey('raw', encoder.encode(env.PEBBLE_SENDER_HASH_KEY), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    const data = JSON.stringify(['pebble-sender-v1', env.PEBBLE_DEVICE_ID, day, ip, ua]);
    const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(data));
    sender.fingerprint = Array.from(new Uint8Array(signature), byte => byte.toString(16).padStart(2, '0')).join('');
    sender.fingerprintDay = day;
  }
  return sender;
}

async function upstream(env, body, preview = false, sender = null) {
  const origin = new URL(env.PEBBLE_API_ORIGIN);
  if (origin.protocol !== 'https:' || origin.username || origin.password || origin.pathname !== '/' || origin.search || origin.hash ||
      !/^[a-zA-Z0-9_-]{1,64}$/.test(env.PEBBLE_DEVICE_ID || '')) throw new Error('configuration');
  const token = env.PEBBLE_WRITER_TOKEN;
  if (!token) throw new Error('configuration');
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 12000);
  try {
    const response = await fetch(new URL(preview ? '/v1/render' : '/v1/devices/' + env.PEBBLE_DEVICE_ID + '/messages', origin), {
      method: 'POST', headers: {
        Authorization: 'Bearer ' + token, Accept: 'application/json', 'User-Agent': 'PebbleMoments/1.0',
        'Content-Type': 'application/json',
        ...(!preview && sender ? { 'X-Pebble-Sender': JSON.stringify(sender) } : {}),
      }, body: body ? JSON.stringify(body) : undefined, signal: controller.signal, redirect: 'manual',
    });
    if (!response.ok) {
      await response.body?.cancel();
      const messages = {
        401: 'Pebble needs its connection settings checked.', 403: 'Pebble needs its connection settings checked.',
        404: 'Pebble is waiting for its first message.', 409: 'Another moment arrived first. Refresh and try again.',
        429: 'A few too many messages at once. Please try again shortly.',
      };
      return json({ error: messages[response.status] || 'Pebble could not save this message. Please try again shortly.' },
        response.status === 404 || response.status === 409 || response.status === 429 ? response.status : 502);
    }
    const queued=await boundedJson(response.body,8192);
    if(preview) {
      if(typeof queued.face !== 'string' || !Object.hasOwn(DEVICE_ASSETS.faces,queued.face)) throw Error('bad_frame');
      return json({face:queued.face});
    }
    if(queued.queued!==true || !Number.isSafeInteger(queued.id) || queued.id<1)throw Error('bad_frame');
    return json({queued:true,id:queued.id,face:body.face},202);
  } finally { clearTimeout(timer); }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (request.method === 'HEAD' && url.pathname === '/') return new Response(null,{headers:SECURITY});
      if (request.method === 'GET') {
        if (url.pathname === '/') return text(PAGE, 'text/html; charset=utf-8');
        if (url.pathname === '/style.css') return text(STYLE+HISTORY_STYLE, 'text/css; charset=utf-8');
        if (url.pathname === '/app.js') return text(APP, 'text/javascript; charset=utf-8');
        if (url.pathname === '/device.js') return text(DEVICE_MODULE, 'text/javascript; charset=utf-8');
        if (url.pathname === '/font-license.txt') return text(FONT_LICENSE, 'text/plain; charset=utf-8');
        if (url.pathname === '/privacy') return text(PRIVACY, 'text/html; charset=utf-8');

      }
      if (request.method === 'POST' && ['/api/moments','/api/preview'].includes(url.pathname)) {
        const preview = url.pathname === '/api/preview';
        const origin = request.headers.get('Origin');
        if ((origin && origin !== url.origin && origin !== EXPECTED_ORIGIN) || request.headers.get('Sec-Fetch-Site') === 'cross-site')
          return json({ error: 'Open this page directly to send a message.' }, 403);
        if (request.headers.get('Content-Type')?.split(';')[0].trim() !== 'application/json')
          return json({ error: 'Please send a text message.' }, 415);
        let input;
        try { input = await boundedJson(request.body, 2048); }
        catch (error) { return json({ error: error.message === 'too_large' ? 'This moment is a little too long.' : 'Please check your message and try again.' }, 400); }
        if (!input || typeof input !== 'object' || Array.isArray(input) || Object.keys(input).some(key => key !== 'message' && (preview || key !== 'face')) ||
            typeof input.message !== 'string' || /[\uD800-\uDFFF]/u.test(input.message) || !input.message.trim() || Array.from(input.message).length > 120 ||
            /[\u0000-\u0009\u000B-\u001F\u007F]/u.test(input.message))
          return json({ error: 'Write a message of 1–120 characters. New lines are welcome.' }, 400);
        if(input.face !== undefined && (typeof input.face !== 'string' || !Object.hasOwn(DEVICE_ASSETS.faces,input.face)))
          return json({error:'Please choose a valid expression.'},400);
        const draft = {message:input.message,state:{kind:'public-message'}};
        if(preview) return await upstream(env,draft,true);
        let face=input.face;
        if(face === undefined) {
          const selection=await upstream(env,draft,true);
          if(!selection.ok) return selection;
          face=(await selection.json()).face;
        }
        return await upstream(env,{...draft,face},false,await senderMetadata(request,env));
      }
      return json({ error: 'This page could not be found.' }, 404);
    } catch (error) {
      // Log metadata only. Never log request bodies, messages, or credentials.
      console.error(JSON.stringify({ event: 'pebble_upstream_failed', kind: ['configuration','bad_frame','too_large','empty'].includes(error.message) ? error.message : error.name, requestId: crypto.randomUUID() }));
      return json({ error: 'Pebble is out of reach just now. Your draft is still here; please try again shortly.' }, 502);
    }
  },
};

const PRIVACY = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pebble / privacy</title><link rel="stylesheet" href="/style.css"></head><body><main class="shell privacy"><h1>Message privacy</h1><p>Messages go to Nikola’s display and are stored on the server. Keep personal or secret information out of your message.</p><p>For troubleshooting and spotting repeated sends, each saved message includes its receipt and delivery-acknowledgement times, approximate country, network number (ASN), browser family, and device category. When enabled, a keyed identifier derived from your IP address and browser user agent groups similar sends within one UTC day. It changes daily and is not proof of identity. Global Privacy Control disables this identifier.</p><p>The application does not store raw IP addresses or full user-agent strings, set tracking cookies, or collect canvas, font, or other active browser fingerprints. Connection details are not sent to the expression classifier. Cloudflare processes connections to operate this service.</p><p>Sender details stay with their message: up to 256 waiting messages and the latest 64 acknowledged messages are retained. Waiting messages remain until delivered; this is a count limit, not a time limit. The device has a separate message history. Only the operator can inspect server metadata; it is not returned to visitors or the display.</p><p>The latest 20 successful sends also remain in this browser’s local storage. “Clear history” removes that local list only. Draft expression previews do not save sender metadata or enqueue messages.</p><p><a href="/">Back to the inbox</a></p></main></body></html>`;

